-- PostgreSQL 15+; synthetic tokens only, no personal case details.
CREATE SCHEMA IF NOT EXISTS social_demo;
CREATE TABLE IF NOT EXISTS social_demo.programmes(programme_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,programme_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,service_type TEXT NOT NULL CHECK(service_type IN('employment_support','skills_training','community_support','referral_service','other')),starts_on DATE,ends_on DATE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','paused','closed')),CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS social_demo.enrolments(enrolment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,enrolment_ref TEXT NOT NULL UNIQUE,programme_id BIGINT NOT NULL REFERENCES social_demo.programmes(programme_id) ON DELETE RESTRICT,subject_token TEXT NOT NULL,opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_service','referred','completed','withdrawn')),closed_at TIMESTAMPTZ,UNIQUE(programme_id,subject_token),CHECK(status<>'completed' OR closed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS social_demo.service_milestones(milestone_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_ref TEXT NOT NULL UNIQUE,enrolment_id BIGINT NOT NULL REFERENCES social_demo.enrolments(enrolment_id) ON DELETE RESTRICT,milestone_type TEXT NOT NULL CHECK(milestone_type IN('assessment_scheduled','training_attended','referral_sent','referral_acknowledged','follow_up','other')),due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','completed','cancelled')),completed_at TIMESTAMPTZ,owner_ref TEXT NOT NULL,summary TEXT NOT NULL,CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS social_demo.milestone_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,milestone_id BIGINT NOT NULL REFERENCES social_demo.service_milestones(milestone_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','completed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_social_enrolment_programme_status ON social_demo.enrolments(programme_id,status);
CREATE INDEX IF NOT EXISTS ix_social_milestones_due ON social_demo.service_milestones(status,due_date) WHERE status NOT IN('completed','cancelled');
CREATE INDEX IF NOT EXISTS ix_social_events_milestone ON social_demo.milestone_events(milestone_id,happened_at DESC,event_id DESC);
